from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Enclosed background is determined by 4-way connectivity.
    exterior = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in exterior:
                exterior.add((nr,nc)); q.append((nr,nc))
    # Color inner boundary cells of cavities. For every 4-connected line
    # component bordering a cavity, color its full 8-neighbor exterior halo.
    enclosed = {(r,c) for r in range(h) for c in range(w)
                if grid[r][c] == 0 and (r,c) not in exterior}
    inner = set()
